// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint256 commitAmount) public {
        vm.assume(amount > 0);
        vm.assume(commitAmount >= amount);
        Reverter reverter = new Reverter();
        address target = address(reverter);
        vm.deal(address(c), commitAmount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.sendMoney(target, amount, "") { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        assertTrue(ok ? balanceBefore - balanceAfter == amount : balanceBefore == balanceAfter);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
